#define DM2_ZONE_COUNT (sizeof(kDm2TouchClickZones) / sizeof(kDm2TouchClickZones[0]))

unsigned int DM2_TOUCHCLICK_Compat_GetZoneCount(void) {
    return (unsigned int)DM2_ZONE_COUNT;
}

int DM2_TOUCHCLICK_Compat_GetZone(unsigned int ordinal,
                                  Dm2TouchClickZonePc34Compat* outZone) {
    if (!outZone || ordinal >= DM2_ZONE_COUNT) return 0;
    *outZone = kDm2TouchClickZones[ordinal];
    return 1;
}

int DM2_TOUCHCLICK_Compat_GetZoneByIndex(
    unsigned int zoneIndex, Dm2TouchClickZonePc34Compat* outZone) {
    unsigned int i;
    if (!outZone) return 0;
    for (i = 0; i < DM2_ZONE_COUNT; ++i) {
        if (kDm2TouchClickZones[i].zoneIndex != zoneIndex) continue;
        *outZone = kDm2TouchClickZones[i];
        return 1;
    }
    return 0;
}

int DM2_TOUCHCLICK_Compat_GetZoneBySourceRecord(
    unsigned int eventIndex, unsigned int rectId, unsigned int buttonMask,
    unsigned int occurrence,
    Dm2TouchClickZonePc34Compat* outZone) {
    return DM2_TOUCHCLICK_Compat_GetSourceRecordContextAt(
        eventIndex, rectId, buttonMask, occurrence, outZone);
}

unsigned int DM2_TOUCHCLICK_Compat_GetSourceRecordContextCount(
    unsigned int eventIndex, unsigned int rectId, unsigned int buttonMask) {
    unsigned int i;
    unsigned int count = 0u;
    for (i = 0; i < DM2_ZONE_COUNT; ++i) {
        const char *evidence = kDm2TouchClickZones[i].sourceEvidence;
        const char *source = evidence ? strstr(evidence, "event 0x") : NULL;
        unsigned int sourceEvent;
        unsigned int sourceRect;
        unsigned int sourceMask;
        if (!source || sscanf(source, "event 0x%x rectid 0x%x w4 0x%x",
                              &sourceEvent, &sourceRect, &sourceMask) != 3)
            continue;
        if (sourceEvent != eventIndex || sourceRect != rectId ||
            sourceMask != buttonMask)
            continue;
        ++count;
    }
    return count;
}

int DM2_TOUCHCLICK_Compat_GetSourceRecordContextAt(
    unsigned int eventIndex, unsigned int rectId, unsigned int buttonMask,
    unsigned int occurrence, Dm2TouchClickZonePc34Compat* outZone) {
    unsigned int i;
    if (!outZone) return 0;
    for (i = 0; i < DM2_ZONE_COUNT; ++i) {
        const char *evidence = kDm2TouchClickZones[i].sourceEvidence;
        const char *source = evidence ? strstr(evidence, "event 0x") : NULL;
        unsigned int sourceEvent;
        unsigned int sourceRect;
        unsigned int sourceMask;
        if (!source || sscanf(source, "event 0x%x rectid 0x%x w4 0x%x",
                              &sourceEvent, &sourceRect, &sourceMask) != 3)
            continue;
        if (sourceEvent != eventIndex || sourceRect != rectId ||
            sourceMask != buttonMask)
            continue;
        if (occurrence != 0u) {
            --occurrence;
            continue;
        }
        *outZone = kDm2TouchClickZones[i];
        return 1;
    }
    return 0;
}

unsigned int DM2_TOUCHCLICK_Compat_GetViewZoneCount(
    Dm2TouchClickViewPc34Compat view) {
    unsigned int count = 0;
    unsigned int i;
    for (i = 0; i < DM2_ZONE_COUNT; ++i) {
        if (kDm2TouchClickZones[i].view == view) ++count;
    }
    return count;
}

int DM2_TOUCHCLICK_Compat_GetViewZone(Dm2TouchClickViewPc34Compat view,
                                      unsigned int viewOrdinal,
                                      Dm2TouchClickZonePc34Compat* outZone) {
    unsigned int seen = 0;
    unsigned int i;
    if (!outZone) return 0;
    for (i = 0; i < DM2_ZONE_COUNT; ++i) {
        if (kDm2TouchClickZones[i].view != view) continue;
        if (seen == viewOrdinal) {
            *outZone = kDm2TouchClickZones[i];
            return 1;
        }
        ++seen;
    }
    return 0;
}

int DM2_TOUCHCLICK_Compat_HitTestInView(Dm2TouchClickViewPc34Compat view,
                                        int screenX, int screenY,
                                        unsigned int buttonMask,
                                        Dm2TouchClickZonePc34Compat* outZone) {
    unsigned int i;
    for (i = 0; i < DM2_ZONE_COUNT; ++i) {
        const Dm2TouchClickZonePc34Compat* zone = &kDm2TouchClickZones[i];
        if (zone->view != view) continue;
        if ((zone->buttonMask & buttonMask) == 0) continue;
        if (screenX < zone->x || screenX >= zone->x + zone->w ||
                screenY < zone->y || screenY >= zone->y + zone->h)
            continue;
        if (outZone) *outZone = *zone;
        return 1;
    }
    return 0;
}

const char* DM2_TOUCHCLICK_Compat_GetViewName(
    Dm2TouchClickViewPc34Compat view) {
    switch (view) {
        case DM2_TOUCH_CLICK_VIEW_MAIN_MENU_PC34_COMPAT: return "main_menu";
        case DM2_TOUCH_CLICK_VIEW_CREDITS_PC34_COMPAT: return "credits";
        case DM2_TOUCH_CLICK_VIEW_SLEEP_PC34_COMPAT: return "sleep";
        case DM2_TOUCH_CLICK_VIEW_PAUSE_PC34_COMPAT: return "pause";
        case DM2_TOUCH_CLICK_VIEW_DIALOG_PC34_COMPAT: return "dialog";
        case DM2_TOUCH_CLICK_VIEW_DUNGEON_PC34_COMPAT: return "dungeon";
        case DM2_TOUCH_CLICK_VIEW_CHAMPION_RIBBON_PC34_COMPAT: return "champion_ribbon";
        case DM2_TOUCH_CLICK_VIEW_CHAMPION_PC34_COMPAT: return "champion";
        case DM2_TOUCH_CLICK_VIEW_INVENTORY_PC34_COMPAT: return "inventory";
        case DM2_TOUCH_CLICK_VIEW_SAVEGAME_SLOTS_PC34_COMPAT: return "savegame_slots";
        default: return "unknown";
    }
}

